  function render(container,{text,title}={}){
    if(!container)return false;text=String(text||'');container.replaceChildren();
    const songTitle=String(title||'').split(' · ')[0].replace(/（(?:現場版|抒情版|動畫版|電視版)・(?:原曲歌詞參考|未同步)）$/, ''), songPack=songReadings[songTitle];
    const entry=songPack&&Object.prototype.hasOwnProperty.call(songPack,text)?songPack[text]:Object.prototype.hasOwnProperty.call(data,text)?data[text]:null;
    const songCorrections=Object.prototype.hasOwnProperty.call(scopedCorrections,songTitle)?scopedCorrections[songTitle]:null;
    const revised=songCorrections&&Object.prototype.hasOwnProperty.call(songCorrections,text)?songCorrections[text]:null;
    const ja=document.createElement('span');ja.className='lyric-ja';
    if(entry&&Array.isArray(entry.segments)&&entry.segments.map(x=>x?.text||'').join('')===text){
      for(const segment of entry.segments){
        if(typeof segment.reading==='string'&&segment.reading){const ruby=document.createElement('ruby');ruby.append(document.createTextNode(segment.text));const rt=document.createElement('rt');rt.textContent=segment.reading;ruby.append(rt);ja.append(ruby);}
        else ja.append(document.createTextNode(String(segment.text||'')));
      }
    }else ja.textContent=text;
    container.append(ja);
    const isJapanese=/[\u3040-\u30ff\u3400-\u9fff\u{20000}-\u{2fa1f}]/u.test(text);
    if(!isJapanese&&!revised)return false;
    if(isJapanese){const romaji=document.createElement('span');romaji.className='lyric-romaji';romaji.textContent=entry?.romaji||'羅馬拼音暫無';container.append(romaji);}
    const zh=document.createElement('span');zh.className='lyric-zh';zh.textContent=revised||entry?.zh||'中文翻譯暫無';container.append(zh);
    return !!entry;
  }
  function hasRevisions(song){
    const title=String(song?.name||'').split(' · ')[0].replace(/（(?:現場版|抒情版|動畫版|電視版)・(?:原曲歌詞參考|未同步)）$/, '');
    const scoped=Object.prototype.hasOwnProperty.call(scopedCorrections,title)?scopedCorrections[title]:null;
    return Array.isArray(song?.lines)&&song.lines.some(text=>
      !!(scoped&&Object.prototype.hasOwnProperty.call(scoped,text)) ||
      !!(Object.prototype.hasOwnProperty.call(data,text)&&data[text]?.zhReviewed===true) ||
      !!(songReadings[title]&&Object.prototype.hasOwnProperty.call(songReadings[title],text)&&songReadings[title][text]?.zhReviewed===true));
  }
  root.LyricReading={register,registerSong,render,hasRevisions};
